inbound.set-body:
@{
			var body = context.Request.Body.As<JObject>(preserveContent: true);
			var model = (string)body["model"] ?? "";

			var isReasoningModel = model.StartsWith("o1") || model.StartsWith("o3")
				|| model.StartsWith("o4") || model.StartsWith("gpt-5");

			if (isReasoningModel)
			{
				// Move the cap across rather than drop it, so the caller still gets the
				// limit it asked for. An explicit max_completion_tokens always wins.
				if (body["max_tokens"] != null)
				{
					if (body["max_completion_tokens"] == null)
					{
						body["max_completion_tokens"] = body["max_tokens"];
					}
					body.Remove("max_tokens");
				}

				// Only the default temperature is allowed, so remove any other value.
				// Sending 1 explicitly is fine and is left alone.
				var temperature = body["temperature"];
				if (temperature != null && temperature.Type != JTokenType.Null
					&& (double)temperature != 1d)
				{
					body.Remove("temperature");
				}
			}

			return body.ToString();
		}
